public class SalesRollupTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.List<Sale> sales = java.util.List.of(
                    new Sale("west", 3.0), new Sale("east", 10.5),
                    new Sale("east", 2.25), new Sale("north", 0.25),
                    new Sale("west", 1.5));
            java.util.Map<String, Double> totals = SalesRollup.totalByRegion(sales);
            check("east total", 12.75, totals.get("east"));
            check("west total", 4.5, totals.get("west"));
            check("single-sale region total", 0.25, totals.get("north"));
            check("three regions in the map", 3, totals.size());
            check("keys come back sorted", "[east, north, west]",
                    new java.util.ArrayList<>(totals.keySet()).toString());

            java.util.Map<String, Double> one =
                    SalesRollup.totalByRegion(java.util.List.of(new Sale("solo", 99.5)));
            check("single sale", 99.5, one.get("solo"));

            java.util.Map<String, Double> none = SalesRollup.totalByRegion(java.util.List.of());
            check("empty input -> empty map", 0, none.size());
        } catch (RuntimeException e) {
            System.out.println("FAIL  totalByRegion usage -- threw " + e.getClass().getSimpleName());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

