record Sale(String region, double amount) {}

public class SalesRollup {

    public static java.util.Map<String, Double> totalByRegion(java.util.List<Sale> sales) {
        return sales.stream()
                .collect(java.util.stream.Collectors.groupingBy(
                        Sale::region,
                        java.util.TreeMap::new,
                        java.util.stream.Collectors.summingDouble(Sale::amount)));
    }
}
